<script setup>
import { computed, ref } from 'vue'
const mode=ref('json'), input=ref(''), status=ref('200')
const statuses={200:'OK',201:'Created',204:'No Content',301:'Moved Permanently',400:'Bad Request',401:'Unauthorized',403:'Forbidden',404:'Not Found',409:'Conflict',422:'Unprocessable Content',429:'Too Many Requests',500:'Internal Server Error',502:'Bad Gateway',503:'Service Unavailable'}
const output=computed(()=>{try{if(mode.value==='json')return JSON.stringify(JSON.parse(input.value),null,2);if(mode.value==='url-encode')return encodeURIComponent(input.value);if(mode.value==='url-decode')return decodeURIComponent(input.value);if(mode.value==='base64-encode')return btoa(unescape(encodeURIComponent(input.value)));if(mode.value==='base64-decode')return decodeURIComponent(escape(atob(input.value)));if(mode.value==='jwt'){const p=input.value.split('.')[1];return JSON.stringify(JSON.parse(atob(p.replace(/-/g,'+').replace(/_/g,'/'))),null,2)}return input.value}catch(e){return `Error: ${e.message}`}})
</script>
<template><section class="mx-auto max-w-7xl px-5 py-10"><div class="mb-8"><div class="badge">Utilities</div><h1 class="mt-3 text-3xl font-bold">Developer Tools</h1><p class="mt-2 text-slate-400">The small things you normally open five different tabs for.</p></div><div class="panel p-5"><div class="mb-5 flex flex-wrap gap-2"><button v-for="[k,l] in [['json','JSON'],['jwt','JWT'],['url-encode','URL Encode'],['url-decode','URL Decode'],['base64-encode','Base64 Encode'],['base64-decode','Base64 Decode']]" :key="k" @click="mode=k" :class="['btn-secondary',mode===k?'!border-cyan-300/40 !text-cyan-300':'']">{{l}}</button></div><div class="grid gap-4 lg:grid-cols-2"><textarea v-model="input" class="input mono min-h-80" placeholder="Paste input…"></textarea><textarea :value="output" readonly class="input mono min-h-80"></textarea></div></div><div class="panel mt-6 p-5"><h2 class="font-bold">HTTP Status Lookup</h2><div class="mt-4 flex gap-3"><input v-model="status" class="input !w-36" placeholder="200"><div class="flex items-center text-lg font-semibold">{{ statuses[status] || 'Unknown / less common status' }}</div></div></div></section></template>
